//! Generated C# files, by Roslyn's convention (design D5 of
//! `add-csharp-analysis`): checked by file name before a file is read,
//! and by its header comment after.

/// Whether a C# file is generated by its name: the last component of
/// `path` ends in `.designer.cs`, `.generated.cs`, `.g.cs` or `.g.i.cs`,
/// or starts with `TemporaryGeneratedFile_`, ignoring case.
#[must_use]
pub fn csharp_generated_name(path: &str) -> bool {
    let name = path.rsplit(['/', '\\']).next().unwrap_or(path);
    let lower = name.to_ascii_lowercase();
    lower.starts_with("temporarygeneratedfile_")
        || [".designer.cs", ".generated.cs", ".g.cs", ".g.i.cs"]
            .iter()
            .any(|ending| lower.ends_with(ending))
}

/// Whether a C# file is generated by its header: a comment before its
/// first code contains `<auto-generated` or `<autogenerated` (compared
/// case-sensitively, as Roslyn does). A byte order mark, whitespace and
/// preprocessor lines may come before the comment. The text is scanned,
/// not parsed, so a generated file that does not parse is recognized
/// too.
#[must_use]
pub fn csharp_generated_header(source: &str) -> bool {
    const MARKERS: [&str; 2] = ["<auto-generated", "<autogenerated"];
    let marked = |comment: &str| MARKERS.iter().any(|m| comment.contains(m));
    let mut rest = source.strip_prefix('\u{feff}').unwrap_or(source);
    loop {
        rest = rest.trim_start();
        let (comment, tail) = if rest.starts_with("//") || rest.starts_with('#') {
            rest.split_once('\n').unwrap_or((rest, ""))
        } else if let Some(body) = rest.strip_prefix("/*") {
            match body.split_once("*/") {
                Some((comment, tail)) => (comment, tail),
                None => (body, ""),
            }
        } else {
            return false;
        };
        // A preprocessor line is skipped, not read as a comment.
        if !rest.starts_with('#') && marked(comment) {
            return true;
        }
        if tail.is_empty() {
            return false;
        }
        rest = tail;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_names() {
        for path in [
            "Forms/Main.Designer.cs",
            "Main.designer.cs",
            "obj/Api.Generated.cs",
            "Views/Index.g.cs",
            "Views/Index.G.I.CS",
            "obj/TemporaryGeneratedFile_036C0B5B.cs",
            "temporarygeneratedfile_x.cs",
            "C:\\src\\Forms\\Main.Designer.cs",
        ] {
            assert!(csharp_generated_name(path), "{path}");
        }
    }

    #[test]
    fn ordinary_names() {
        for path in [
            "src/Cart.cs",
            "src/Designer.cs",
            "src/Log.cs",
            "src/g.cs",
            "src/Generated/Cart.cs",
            "Main.Designer.cs.bak",
            "src/MyTemporaryGeneratedFile_x.cs",
        ] {
            assert!(!csharp_generated_name(path), "{path}");
        }
    }

    #[test]
    fn generated_headers() {
        for source in [
            "// <auto-generated />\nusing System;\n",
            "//------\n// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n//------\nnamespace A;\n",
            "\u{feff}// <autogenerated/>\nclass A { }\n",
            "#nullable disable\n\n// <auto-generated />\nclass A { }\n",
            "  /* <auto-generated> */\nclass A { }\n",
            "/*\n * Licensed.\n */\n// <auto-generated/>\nclass A { }\n",
            // A generated file that does not parse is still generated.
            "// <auto-generated />\nclass {{{\n",
        ] {
            assert!(csharp_generated_header(source), "{source:?}");
        }
    }

    #[test]
    fn ordinary_headers() {
        for source in [
            "",
            "class A { }\n",
            "// Written by hand.\nclass A { }\n",
            "using System;\n// <auto-generated />\nclass A { }\n",
            "class A { } // <auto-generated />\n",
            "// <Auto-Generated />\nclass A { }\n",
        ] {
            assert!(!csharp_generated_header(source), "{source:?}");
        }
    }
}
